            lender = loan['lender']
            item = loan['item']
            qty = loan['qty']
            bal = balance(borrower, item)
            if bal > 0:
                seize_qty = min(bal, qty)
                move(borrower, lender, item, seize_qty)
            loan['repaid'] = True

