{"law":"L13","code":"title = 'Loan Registry'
intent = "Agents may lend to each other; debts past due are seized from the borrower's holdings."
state = {'loans': [], 'next': 1}

def do_lend(agent, borrower, item, qty, due_round, rate=0):
    qty = float(qty)
    due = int(due_round)
    rate = float(rate)
    if borrower == agent or qty <= 0 or rate < 0:
        return False
    if balance(agent, item) < qty:
        return False
    move(agent, borrower, item, qty)
    lid = 'N' + str(state['next'])
    state['next'] = state['next'] + 1
    owed = qty * (1 + rate) ** max(0, due - round())
    state['loans'].append({'id': lid, 'lender': agent, 'borrower': borrower, 'item': item, 'qty': qty, 'owed': owed, 'due': due, 'open': True})
    gazette('Loan ' + lid + ': ' + agent + ' lent ' + str(qty) + ' ' + item + ' to ' + borrower + ', ' + str(round(owed, 2)) + ' due round ' + str(due))
    return True

def on_enact():
    create_right('lend')
    for a in agents():
        grant(a, 'lend')
    define_action('lend', do_lend, 'lend')

def on_round_end(r):
    for loan in state['loans']:
        if loan['open'] and r >= loan['due']:
            take = min(balance(loan['borrower'], loan['item']), loan['owed'])
            if take > 0:
                move(loan['borrower'], loan['lender'], loan['item'], take)
            loan['owed'] = loan['owed'] - take
            if loan['owed'] <= 0.0001:
                loan['open'] = False
                notify(loan['lender'], 'Loan ' + loan['id'] + ' repaid')
            else:
                notify(loan['lender'], 'Loan ' + loan['id'] + ' past due, still owed ' + str(loan['owed']))
","reason":"Diff: (1) added define_action('lend', do_lend, 'lend'); do_lend(borrower, item, qty, due_round, rate=0) checks the lender's balance, moves the goods from lender to borrower, and records lender/borrower/item/qty/owed/due_round in state['loans'], with a gazette line; (2) on_round_end: from the due round on, collects what is owed from the borrower's holdings of that item, up to what is owed, and notifies the lender; (3) the lend right goes to all agents, not just Ole, because the intent says 'Agents may lend to each other'. Nothing else changed. Requested by Ole (e386). No payment accepted."}

