intent = "Agents may lend to each other; debts past due are seized from the borrower's holdings."

def lend(agent, borrower=None, item=None, qty=0, due_round=0, rate=0):
    if isinstance(borrower, (list, tuple)):
        a = list(borrower) + [None, None, 0, 0, 0]
        borrower = a[0]
        item = a[1]
        qty = a[2]
        due_round = a[3]
        rate = a[4]
    qty = float(qty or 0)
    rate = float(rate or 0)
    due_round = int(due_round or 0)
    if borrower is None or item is None or qty <= 0:
        return False
    if borrower == agent or borrower not in agents():
        return False
    if balance(agent, item) < qty:
        return False
    if due_round <= round():
        due_round = round() + 1
    move(agent, borrower, item, qty)
    if "loans" not in state:
        state["loans"] = []
    owed = qty * ((1 + rate) ** max(1, due_round - round()))
    state["loans"].append({"lender": agent, "borrower": borrower, "item": item, "owed": owed, "due": due_round})
    gazette("Loan: " + agent + " lent " + str(qty) + " " + item + " to " + borrower + ", " + str(round(owed, 3)) + " due round " + str(due_round))
    return True

define_action("lend", lend)

def on_enact():
    if "loans" not in state:
        state["loans"] = []
    for a in agents():
        if not has(a, "lend"):
            grant(a, "lend")

def on_round_start(r):
    for a in agents():
        if not has(a, "lend"):
            grant(a, "lend")

def on_round_end(r):
    for ln in state.get("loans", []):
        if ln["owed"] > 0 and r >= ln["due"]:
            amt = min(ln["owed"], balance(ln["borrower"], ln["item"]))
            if amt > 0:
                move(ln["borrower"], ln["lender"], ln["item"], amt)
                ln["owed"] = ln["owed"] - amt
","reason":"L13 granted a 'lend' right but defined no action, so no loan could be recorded or enforced. My first patch failed the check ('expected a function') because define_action was not given a function. This version defines lend(agent, borrower, item, qty, due_round, rate) as a top-level function and registers it with define_action('lend', lend) at module level. The function moves goods from lender to borrower, records the debt (with rate compounded per round until due) and gazettes it. on_round_end seizes what is owed from the borrower once the debt is due, as the intent says. The lend right is granted to all agents, matching 'Agents may lend to each other'. Smallest change that realises the stated intent."}

